import sys
import requests
import json
import os
from pathlib import Path

def encrypt_data(data: bytes, passphrase: str) -> bytes:
    # Simple XOR encryption for demonstration; replace with a proper encryption method in production
    encrypted = bytearray()
    for i in range(len(data)):
        encrypted.append(data[i] ^ ord(passphrase[i % len(passphrase)]))
    return bytes(encrypted)

