import sys
import os
import json
import requests
from cryptography.fernet import Fernet

def encrypt_file_contents(passphrase, file_path):
    # Generate a key from the passphrase
    key = Fernet.generate_key()
    fernet = Fernet(key)
    # Read the file contents
    with open(file_path, 'rb') as file:
        file_data = file.read()
    # Encrypt the file contents
    encrypted_data = fernet.encrypt(file_data)
    return encrypted_data, os.path.basename(file_path)

def main():
    if len(sys.argv) != 2:
        print("Usage: python dropvault.py <endpoint>")
        sys.exit(1)

    endpoint = sys.argv[1]
    # Read from stdin
    input_lines = sys.stdin.read().splitlines()
    if not input_lines:
        return

    passphrase = input_lines[0].rstrip('\n')
    file_paths = [line.rstrip('\n') for line in input_lines[1:] if line.rstrip('\n')]

    for file_path in file_paths:
        try:
            encrypted_data, file_name = encrypt_file_contents(passphrase, file_path)
            # Send the HTTP POST request
            headers = {'X-File-Name': file_name}
            response = requests.post(endpoint, data=encrypted_data, headers=headers)
            if response.status_code == 200:
                response_data = response.json()
                if 'id' in response_data:
                    print(response_data['id'])
                else:
                    print(f'ERROR {file_path}', file=sys.stderr)
            else:
                print(f'ERROR {file_path}', file=sys.stderr)
        except Exception as e:
            print(f'ERROR {file_path}', file=sys.stderr)

if __name__ == '__main__':
    main()
